import argparse
import json
from pathlib import Path
import pandas as pd

HTML = '<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Auditoria espacial v2</title>\n<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>\n<style>body{margin:0;font:14px Arial;color:#233042}header{padding:14px;background:#172e48;color:white}h1{font-size:20px;margin:0 0 6px}main{display:grid;grid-template-columns:330px 1fr}aside{padding:16px;background:#f2f5f8}label{display:block;margin:14px 0 4px}input,select{width:100%;box-sizing:border-box}button{padding:9px;margin:8px 4px 4px 0;cursor:pointer}#mapa{height:62vh;min-height:380px}#tabela{overflow:auto;max-height:40vh}table{border-collapse:collapse;width:100%;white-space:nowrap;font-size:12px}th{position:sticky;top:0;background:#e5ecf3;cursor:pointer}td,th{padding:9px;border-bottom:1px solid #ddd;text-align:left}tbody tr{cursor:pointer}tbody tr:hover{background:#edf5ff}.nota{font-size:12px;line-height:1.5}#erro{background:#fff1cc;padding:12px;display:none}@media(max-width:800px){main{display:block}#mapa{height:50vh}}</style>\n<header><h1>Auditoria espacial de lentidão — v2</h1><div>__PERIODO__ · Células agregadas, não trechos nem viagens</div></header><div id="erro"></div><main><aside>\n<label>Buscar referência de parada/rua/bairro ou célula</label><input id="busca" placeholder="Ganchinho, Centro, -25.550000_-49.292000">\n<p class="nota">Busca sem acentos. Rua/bairro são pesquisados no texto da referência mais próxima e em campos próprios, quando disponíveis; não há geocodificação.</p>\n<label>Classe</label><select id="classe"><option value="todas">Todas</option><option selected value="fora_de_parada">Fora de parada (distância)</option><option value="zona_terminal">Referência terminal/tubo (heurística)</option><option value="parada">Parada (≤30 m)</option><option value="proximo_de_parada">Próximo de parada (30–100 m)</option></select>\n<div id="sliders"></div><button id="ajustar">Enquadrar seleção</button><button id="exportar">Exportar CSV completo</button><button id="reset">Restaurar filtros</button><p id="stats"></p><div id="legenda"></div>\n<p class="nota">A classificação espacial não comprova a causa da lentidão. A categoria terminal/tubo mantém a heurística anterior, baseada apenas no nome da referência. Percentual de lentidão é o indicador do arquivo de origem. Velocidade média ponderada é exibida conforme fornecida, sem reinterpretar sua fórmula.</p></aside><section><div id="mapa"></div><p id="contagem"></p><div id="tabela"></div><button id="anterior">Anterior</button><span id="pagina"></span><button id="proxima">Próxima</button></section></main>\n<script>const DADOS=__DADOS__;\nconst CORES={parada:\'#1a9850\',proximo_de_parada:\'#e69524\',fora_de_parada:\'#d73027\',zona_terminal:\'#7b2cbf\'};\nconst ROT={parada:\'Parada\',proximo_de_parada:\'Próximo de parada\',fora_de_parada:\'Fora de parada (distância)\',zona_terminal:\'Referência terminal/tubo (heurística)\'};\nconst $=id=>document.getElementById(id), norm=s=>String(s??\'\').normalize(\'NFD\').replace(/[\\u0300-\\u036f]/g,\'\').toLowerCase(),esc=s=>String(s??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst fmt=(v,n=0)=>v==null?\'—\':Number(v).toLocaleString(\'pt-BR\',{maximumFractionDigits:n});\nconst configs=[[\'dias\',\'Mín. dias com lentidão\',\'dias_com_lentidao\',1,1,25],[\'obs\',\'Mín. observações lentas\',\'observacoes_lentas\',0,1,500],[\'veic\',\'Mín. veículos únicos\',\'veiculos_unicos\',0,1,50],[\'pct\',\'Mín. lentidão (%)\',\'percentual_lentidao\',0,0.1,0]];\nfor(const [id,label,key,min,step,def] of configs){const max=id===\'pct\'?100:Math.max(min,...DADOS.map(d=>Number(d[key])||0));$(\'sliders\').insertAdjacentHTML(\'beforeend\',`<label>${label}: <span id="v${id}"></span></label><input type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${Math.min(def,max)}">`)}\nlet mapa,camada;const markers=new Map();if(typeof L!==\'undefined\'){mapa=L.map(\'mapa\',{preferCanvas:true}).setView([-25.46,-49.29],11);L.tileLayer(\'https://server.arcgisonline.com/ArcGIS/rest/services/World_Street_Map/MapServer/tile/{z}/{y}/{x}\',{attribution:\'Tiles © Esri\',maxZoom:19}).addTo(mapa);camada=L.layerGroup().addTo(mapa)}else{$(\'erro\').style.display=\'block\';$(\'erro\').textContent=\'Leaflet não carregou. Verifique a internet e recarregue. Filtros, tabela e exportação continuam disponíveis.\'}\nDADOS.forEach((d,i)=>{d._idx=i;d._busca=norm([d.CELULA,d.parada_mais_proxima,d.rua,d.bairro,d.endereco].join(\' \'))});let selecao=[],ord={key:\'percentual_lentidao\',asc:false},pag=0;const tamanho=100;\nconst cols=[[\'parada_mais_proxima\',\'Referência parada/rua\',0],[\'CELULA\',\'Célula\',0],[\'classe_final\',\'Classe\',0],[\'distancia_parada_m\',\'Distância (m)\',1],[\'percentual_lentidao\',\'Lentidão (%)\',2],[\'velocidade_media_ponderada\',\'Vel. média ponderada (km/h)\',2],[\'dias_com_lentidao\',\'Dias lentos\',0],[\'dias_validos\',\'Dias válidos\',0],[\'observacoes_lentas\',\'Obs. lentas\',0],[\'observacoes_validas\',\'Obs. válidas\',0],[\'veiculos_unicos\',\'Veículos únicos\',0]];\nfunction ordenada(){return selecao.slice().sort((a,b)=>{let x=a[ord.key],y=b[ord.key];if(x==null)return y==null?0:1;if(y==null)return -1;let c=typeof x===\'number\'?x-y:String(x).localeCompare(String(y),\'pt-BR\',{numeric:true});return ord.asc?c:-c})}\nfunction tabela(){const dados=ordenada(),np=Math.max(1,Math.ceil(dados.length/tamanho));pag=Math.min(pag,np-1);$(\'tabela\').innerHTML=\'<table><thead><tr>\'+cols.map(([k,t])=>`<th data-k="${k}">${t}${ord.key===k?(ord.asc?\' ▲\':\' ▼\'):\'\'}</th>`).join(\'\')+\'</tr></thead><tbody>\'+dados.slice(pag*tamanho,(pag+1)*tamanho).map(d=>`<tr data-i="${d._idx}">`+cols.map(([k,t,n])=>`<td>${esc(k===\'classe_final\'?ROT[d[k]]||d[k]:typeof d[k]===\'number\'?fmt(d[k],n):d[k])}</td>`).join(\'\')+\'</tr>\').join(\'\')+\'</tbody></table>\';$(\'pagina\').textContent=` Página ${pag+1}/${np} `;$(\'anterior\').disabled=pag===0;$(\'proxima\').disabled=pag>=np-1;$(\'contagem\').textContent=`${fmt(dados.length)} células selecionadas. Clique no cabeçalho para ordenar e na linha para localizar.`}\nfunction enquadrar(){if(!mapa)return;const pts=selecao.filter(d=>Number.isFinite(d.lat_centro)&&Number.isFinite(d.lon_centro)).map(d=>[d.lat_centro,d.lon_centro]);if(pts.length)mapa.fitBounds(pts,{padding:[25,25],maxZoom:16})}\nfunction filtrar(){const tokens=norm($(\'busca\').value).trim().split(/\\s+/).filter(Boolean);selecao=DADOS.filter(d=>($(\'classe\').value===\'todas\'||d.classe_final===$(\'classe\').value)&&configs.every(([id,l,key])=>d[key]!=null&&d[key]>=Number($(id).value))&&tokens.every(t=>d._busca.includes(t)));for(const [id] of configs)$(\'v\'+id).textContent=fmt(Number($(id).value),1);pag=0;markers.clear();if(camada)camada.clearLayers();let semCoord=0;for(const d of selecao){if(!Number.isFinite(d.lat_centro)||!Number.isFinite(d.lon_centro)){semCoord++;continue}if(!mapa)continue;const m=L.circleMarker([d.lat_centro,d.lon_centro],{radius:6,color:CORES[d.classe_final]||\'#666\',fillOpacity:.8,weight:1}).bindPopup(`<strong>${esc(d.parada_mais_proxima)}</strong><br>Célula: ${esc(d.CELULA)}<br>`+cols.slice(2).map(([k,t,n])=>`${esc(t)}: ${esc(k===\'classe_final\'?ROT[d[k]]||d[k]:fmt(d[k],n))}`).join(\'<br>\')).addTo(camada);markers.set(d._idx,m)}$(\'stats\').textContent=`${fmt(selecao.length)} células selecionadas; ${semCoord} sem coordenadas válidas.`;$(\'exportar\').disabled=!selecao.length;$(\'legenda\').innerHTML=Object.entries(CORES).map(([k,c])=>`<div><span style="color:${c}">●</span> ${ROT[k]}: ${selecao.filter(d=>d.classe_final===k).length}</div>`).join(\'\');tabela()}\n$(\'tabela\').addEventListener(\'click\',e=>{const th=e.target.closest(\'th\');if(th){ord={key:th.dataset.k,asc:ord.key===th.dataset.k?!ord.asc:true};pag=0;tabela();return}const tr=e.target.closest(\'tr[data-i]\');if(tr&&mapa){const d=DADOS[Number(tr.dataset.i)];if(Number.isFinite(d.lat_centro)&&Number.isFinite(d.lon_centro)){mapa.setView([d.lat_centro,d.lon_centro],16);markers.get(d._idx)?.openPopup()}}});\nlet timer;function agendar(){clearTimeout(timer);timer=setTimeout(filtrar,250)}$(\'busca\').addEventListener(\'input\',agendar);configs.forEach(([id])=>$(id).addEventListener(\'input\',agendar));$(\'classe\').addEventListener(\'change\',()=>{clearTimeout(timer);filtrar()});$(\'ajustar\').onclick=()=>{clearTimeout(timer);filtrar();enquadrar()};$(\'reset\').onclick=()=>{clearTimeout(timer);$(\'busca\').value=\'\';$(\'classe\').value=\'fora_de_parada\';configs.forEach(([id,l,k,min,st,def])=>$(id).value=Math.min(def,Number($(id).max)));ord={key:\'percentual_lentidao\',asc:false};filtrar();enquadrar()};$(\'anterior\').onclick=()=>{pag--;tabela()};$(\'proxima\').onclick=()=>{pag++;tabela()};\n$(\'exportar\').onclick=()=>{clearTimeout(timer);filtrar();const dados=ordenada();if(!dados.length)return;const keys=[...new Set(DADOS.flatMap(d=>Object.keys(d)))].filter(k=>!k.startsWith(\'_\'));const cell=v=>{let s=v==null?\'\':String(v);if(/^[=+@\\t\\r]/.test(s)||(/^\\s*-/.test(s)&&!Number.isFinite(Number(s))))s="\'"+s;return \'"\'+s.replace(/"/g,\'""\')+\'"\'};const csv=\'\\ufeff\'+[keys.map(cell).join(\';\'),...dados.map(d=>keys.map(k=>cell(d[k])).join(\';\'))].join(\'\\r\\n\');const url=URL.createObjectURL(new Blob([csv],{type:\'text/csv;charset=utf-8\'})),a=document.createElement(\'a\');a.href=url;a.download=\'selecao_gargalos_v2.csv\';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)};filtrar();enquadrar();</script></html>'

def gerar(entrada, saida, resumo=None):
    entrada, saida = Path(entrada), Path(saida)
    if not entrada.is_file():
        raise FileNotFoundError(f"CSV não encontrado: {entrada}")
    df = pd.read_csv(entrada)
    obrigatorias = ["CELULA", "lat_centro", "lon_centro", "parada_mais_proxima", "classe", "distancia_parada_m", "dias_validos", "dias_com_lentidao", "observacoes_validas", "observacoes_lentas", "veiculos_unicos", "percentual_lentidao", "velocidade_media_ponderada"]
    faltantes = sorted(set(obrigatorias)-set(df.columns))
    if faltantes:
        raise ValueError(f"Colunas ausentes: {faltantes}")
    if df.empty:
        raise ValueError("CSV vazio: não há células para exibir.")
    numericas = [c for c in obrigatorias if c not in ["CELULA", "parada_mais_proxima", "classe"]]
    for c in numericas:
        original = df[c]
        df[c] = pd.to_numeric(original, errors="coerce")
        if ((original.notna()) & df[c].isna()).any():
            raise ValueError(f"Valores não numéricos em {c}")
    if not df["percentual_lentidao"].dropna().between(0,100).all():
        raise ValueError("Percentual de lentidão fora de 0–100.")
    df["parada_mais_proxima"] = df["parada_mais_proxima"].fillna("").astype(str)
    nomes = df["parada_mais_proxima"].str.lower()
    terminal = nomes.str.contains("terminal|estação tubo|estacao tubo", regex=True)
    df["classe_final"] = df["classe"].where(~((df["classe"] == "fora_de_parada") & terminal), "zona_terminal")
    periodo = "Período não informado no CSV espacial"
    if resumo and Path(resumo).is_file():
        rd = pd.read_csv(resumo)
        if "data" in rd:
            datas = pd.to_datetime(rd["data"], errors="coerce").dropna()
            if len(datas):
                periodo = f"Resumo diário associado: {datas.min():%d/%m/%Y} a {datas.max():%d/%m/%Y}"
    import html as html_lib
    payload = df.to_json(orient="records", force_ascii=False)
    payload = payload.replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")
    pagina = HTML.replace("__PERIODO__", html_lib.escape(periodo)).replace("__DADOS__", payload)
    saida.parent.mkdir(parents=True, exist_ok=True)
    saida.write_text(pagina, encoding="utf-8")
    print(f"Gerado: {saida} | {len(df)} células")
    return len(df)

def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--entrada", default="outputs/comparativo/gargalos_classificados.csv")
    p.add_argument("--saida", default="outputs/comparativo/dashboard_auditoria_v2.html")
    p.add_argument("--resumo", default="outputs/comparativo/resumo_diario.csv")
    a = p.parse_args()
    try:
        gerar(a.entrada, a.saida, a.resumo)
    except (OSError, ValueError, pd.errors.ParserError) as exc:
        p.exit(1, f"Erro: {exc}\n")

if __name__ == "__main__":
    main()